// AP Precalculus MCQ bank (103 questions).
// Content ported verbatim from the AP Precalculus section of whap-one.vercel.app.
// Do not reword: question text, rubrics, and LaTeX are exact copies.

import type { PrecalcMCQ, MCQChoice, CalcMode } from "../types";

const V = (
  id: string,
  unitId: 1 | 2 | 3,
  topicId: string,
  calcMode: CalcMode,
  difficulty: 1 | 2 | 3,
  skill: string,
  questionText: string,
  choices: MCQChoice[],
  correctChoice: string,
  stimulusText?: string,
): PrecalcMCQ => ({ id, unitId, topicId, calcMode, difficulty, skill, questionText, choices, correctChoice, stimulusText, source: "precalc-original" });

export const mcqBank: PrecalcMCQ[] = [V(`mc-1-01`,1,`1.2`,`no-calc`,1,`Procedural and Symbolic Fluency`,`What is the average rate of change of $f(x) = x^2 + 3x$ on the interval $[1, 4]$?`,[{letter:`A`,text:`$5$`,explanation:`Incorrect. This would be $f(4) - f(1)/4 = 28-4/4 = 6$ which is also wrong; you also need to divide by $(b-a) = 3$, not $b$.`},{letter:`B`,text:`$8$`,explanation:`Correct. $f(4) = 16 + 12 = 28$, $f(1) = 1 + 3 = 4$. AROC $= (28 - 4)/(4 - 1) = 24/3 = 8$.`},{letter:`C`,text:`$24$`,explanation:`Incorrect. This is $f(4) - f(1) = 28 - 4 = 24$ but you forgot to divide by $b - a = 3$.`},{letter:`D`,text:`$12$`,explanation:`Incorrect. This is the average of $f(1)$ and $f(4)$, not the average rate of change.`}],`B`),V(`mc-1-02`,1,`1.4`,`no-calc`,2,`Multiple Representations`,`A polynomial $p(x)$ has zeros at $x = -2$, $x = 0$, and $x = 3$, all with multiplicity 1, and a leading coefficient of $-1$. Which expression is $p(x)$?`,[{letter:`A`,text:`$-(x+2)(x)(x-3)$`,explanation:`Correct. Zeros at $-2, 0, 3$ give factors $(x+2)$, $x$, $(x-3)$. Leading coefficient $-1$ means we multiply by $-1$.`},{letter:`B`,text:`$-(x-2)(x)(x+3)$`,explanation:`Incorrect. Zero at $-2$ gives factor $(x+2)$, not $(x-2)$. Sign convention is opposite.`},{letter:`C`,text:`$(x+2)(x)(x-3)$`,explanation:`Incorrect. This has the right zeros but a positive leading coefficient.`},{letter:`D`,text:`$-(x+2)(x-3)$`,explanation:`Incorrect. Missing the factor for the zero at $x = 0$.`}],`A`),V(`mc-1-03`,1,`1.6`,`no-calc`,1,`Communication and Reasoning`,`Which of the following best describes the end behavior of $p(x) = -3x^4 + 2x^2 - 5$?`,[{letter:`A`,text:`$\\lim_{x \\to \\infty} p(x) = \\infty$ and $\\lim_{x \\to -\\infty} p(x) = \\infty$.`,explanation:`Incorrect. The leading term is $-3x^4$. Even degree but negative leading coefficient means both ends $\\to -\\infty$.`},{letter:`B`,text:`$\\lim_{x \\to \\infty} p(x) = -\\infty$ and $\\lim_{x \\to -\\infty} p(x) = -\\infty$.`,explanation:`Correct. Leading term $-3x^4$ is even degree with negative coefficient. As $|x| \\to \\infty$, $-3x^4 \\to -\\infty$.`},{letter:`C`,text:`$\\lim_{x \\to \\infty} p(x) = \\infty$ and $\\lim_{x \\to -\\infty} p(x) = -\\infty$.`,explanation:`Incorrect. This describes odd-degree behavior with positive leading coefficient. Our polynomial has even degree.`},{letter:`D`,text:`$\\lim_{x \\to \\infty} p(x) = -\\infty$ and $\\lim_{x \\to -\\infty} p(x) = \\infty$.`,explanation:`Incorrect. This describes odd-degree behavior with negative leading coefficient.`}],`B`),V(`mc-1-04`,1,`1.7`,`no-calc`,2,`Procedural and Symbolic Fluency`,`What is the horizontal asymptote of $r(x) = \\dfrac{6x^3 - 2x + 1}{3x^3 + 5x^2}$?`,[{letter:`A`,text:`$y = 0$`,explanation:`Incorrect. $y = 0$ is the horizontal asymptote only when numerator degree is LESS than denominator degree.`},{letter:`B`,text:`$y = 2$`,explanation:`Correct. Numerator and denominator both have degree 3. The horizontal asymptote is the ratio of leading coefficients: $6/3 = 2$.`},{letter:`C`,text:`$y = 6$`,explanation:`Incorrect. You used only the numerator's leading coefficient. The asymptote is the ratio.`},{letter:`D`,text:`No horizontal asymptote.`,explanation:`Incorrect. No horizontal asymptote requires numerator degree to exceed denominator degree.`}],`B`),V(`mc-1-05`,1,`1.10`,`no-calc`,2,`Multiple Representations`,`For $r(x) = \\dfrac{(x-3)(x+1)}{(x-3)(x+4)}$, which of the following is true?`,[{letter:`A`,text:`Vertical asymptote at $x = 3$ and at $x = -4$.`,explanation:`Incorrect. The factor $(x-3)$ cancels between numerator and denominator, leaving a HOLE at $x = 3$, not a vertical asymptote.`},{letter:`B`,text:`Vertical asymptote at $x = -4$ only; hole at $x = 3$.`,explanation:`Correct. Cancel $(x-3)$ to get the simplified form $\\frac{x+1}{x+4}$ for $x \\ne 3$. Vertical asymptote where $x + 4 = 0 \\Rightarrow x = -4$. Hole at $x = 3$.`},{letter:`C`,text:`Hole at $x = -4$ and at $x = 3$.`,explanation:`Incorrect. $(x+4)$ does not cancel, so $x = -4$ is a vertical asymptote.`},{letter:`D`,text:`No asymptotes or holes.`,explanation:`Incorrect. The denominator zeros are visible in the original form.`}],`B`),V(`mc-1-06`,1,`1.12`,`no-calc`,2,`Procedural and Symbolic Fluency`,`If $g(x) = -2 f(x - 3) + 5$, which transformation has been applied to $f$?`,[{letter:`A`,text:`Shift right 3, vertical stretch by 2, reflect across $x$-axis, shift up 5.`,explanation:`Correct. Inside: $x - 3$ shifts RIGHT by 3. Outside: $-2 \\cdot f(\\ldots)$ stretches vertically by factor 2 and reflects across the $x$-axis. Then $+5$ shifts up 5.`},{letter:`B`,text:`Shift left 3, vertical compression by 2, reflect across $y$-axis, shift up 5.`,explanation:`Incorrect on multiple counts: $x-3$ shifts RIGHT not left; $-2$ is a stretch by 2 (not compression), and reflects across the $x$-axis, not $y$.`},{letter:`C`,text:`Shift right 3, vertical compression by 1/2, shift up 5.`,explanation:`Incorrect. The $-2$ is a stretch by 2 with reflection, not a compression.`},{letter:`D`,text:`Shift right 5, stretch by 2.`,explanation:`Incorrect. $+5$ outside the function shifts vertically up by 5, not horizontally.`}],`A`),V(`mc-1-07`,1,`1.5`,`no-calc`,3,`Communication and Reasoning`,`A polynomial of degree 5 with real coefficients has zeros at $x = 1$ (multiplicity 2) and at $x = 2 + 3i$. How many real zeros does this polynomial have, counting multiplicity?`,[{letter:`A`,text:`1`,explanation:`Incorrect. The zero at $x = 1$ has multiplicity 2, so it counts as 2 real zeros.`},{letter:`B`,text:`2`,explanation:`Incorrect. This counts only the multiplicity at $x = 1$. There must be one additional real zero — see why below.`},{letter:`C`,text:`3`,explanation:`Correct. Total is 5 zeros (degree 5). $x=1$ contributes 2 (with multiplicity). $x = 2 + 3i$ requires its conjugate $2 - 3i$ for real coefficients, contributing 2 complex zeros. That accounts for $2 + 2 = 4$, leaving $5 - 4 = 1$ more real zero. Real zeros total: $2 + 1 = 3$.`},{letter:`D`,text:`5`,explanation:`Incorrect. Two of the zeros are non-real complex.`}],`C`),V(`mc-1-08`,1,`1.3`,`no-calc`,2,`Multiple Representations`,`The table shows values of $f$ at equally-spaced inputs. Which of the following is most consistent with $f$ being a quadratic function?`,[{letter:`A`,text:`First differences of $f(x)$ are constant.`,explanation:`Incorrect. Constant first differences indicate a LINEAR function.`},{letter:`B`,text:`Second differences of $f(x)$ are constant.`,explanation:`Correct. For a quadratic with equally-spaced inputs, second differences are constant: $f(x) = ax^2 + bx + c$ has second difference $2a \\Delta x^2$.`},{letter:`C`,text:`First ratios of $f(x)$ are constant.`,explanation:`Incorrect. Constant first ratios indicate an EXPONENTIAL function.`},{letter:`D`,text:`Third differences of $f(x)$ are constant.`,explanation:`Incorrect. Constant third differences indicate a CUBIC function.`}],`B`,`For a function $f$ with values at $x = 0, 1, 2, 3, 4, \\ldots$ (equally spaced), differences are computed as $\\Delta f(x) = f(x+1) - f(x)$.`),V(`mc-1-09`,1,`1.11`,`no-calc`,3,`Procedural and Symbolic Fluency`,`Find the slant asymptote of $r(x) = \\dfrac{2x^2 - 5x + 1}{x - 2}$.`,[{letter:`A`,text:`$y = 2x - 1$`,explanation:`Correct. Polynomial division: $2x^2 - 5x + 1 = (x - 2)(2x - 1) - 1$. The slant asymptote is $y = 2x - 1$ (the quotient).`},{letter:`B`,text:`$y = 2x + 1$`,explanation:`Incorrect. Sign error in division.`},{letter:`C`,text:`$y = 2x$`,explanation:`Incorrect. The full quotient has a constant term.`},{letter:`D`,text:`No slant asymptote (degree difference is too large).`,explanation:`Incorrect. The numerator is degree 2, denominator is degree 1, difference is exactly 1 — slant asymptote exists.`}],`A`),V(`mc-1-10`,1,`1.14`,`calc-required`,2,`Multiple Representations`,`A rational function $r$ has a vertical asymptote at $x = 2$, a horizontal asymptote at $y = 3$, and passes through $(0, 0)$. Which of the following is a valid form for $r(x)$?`,[{letter:`A`,text:`$r(x) = \\dfrac{3x}{x-2}$`,explanation:`Correct. Denominator zero at $x = 2$ gives the vertical asymptote. Numerator and denominator both degree 1 with ratio of leading coefficients $3/1 = 3$ gives horizontal asymptote $y = 3$. At $x = 0$: $r(0) = 0/(-2) = 0$. ✓`},{letter:`B`,text:`$r(x) = \\dfrac{3}{x-2}$`,explanation:`Incorrect. Numerator degree (0) is less than denominator degree (1), so horizontal asymptote is $y = 0$, not $y = 3$.`},{letter:`C`,text:`$r(x) = \\dfrac{x}{x-2}$`,explanation:`Incorrect. Horizontal asymptote here is $y = 1$, not $y = 3$.`},{letter:`D`,text:`$r(x) = \\dfrac{3x}{x+2}$`,explanation:`Incorrect. Vertical asymptote here is at $x = -2$, not $x = 2$.`}],`A`),V(`mc-1-11`,1,`1.7`,`no-calc`,1,`Procedural and Symbolic Fluency`,`What is the horizontal asymptote of $r(x) = \\dfrac{4x + 1}{x^2 + 5}$?`,[{letter:`A`,text:`$y = 0$`,explanation:`Correct. Numerator degree (1) is less than denominator degree (2), so horizontal asymptote is $y = 0$.`},{letter:`B`,text:`$y = 4$`,explanation:`Incorrect. Ratio of leading coefficients only applies when degrees are equal.`},{letter:`C`,text:`$y = 1/5$`,explanation:`Incorrect. The ratio of constants ($1/5$) is the y-intercept, not the asymptote.`},{letter:`D`,text:`No horizontal asymptote.`,explanation:`Incorrect. Numerator degree is less than denominator degree, so $y = 0$ IS the asymptote.`}],`A`),V(`mc-1-12`,1,`1.8`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Find all zeros of $r(x) = \\dfrac{x^2 - 9}{x^2 - x - 6}$.`,[{letter:`A`,text:`$x = -3, x = 3$`,explanation:`Incorrect. $x = 3$ is a zero of both numerator and denominator, so it is a HOLE, not a zero.`},{letter:`B`,text:`$x = -3$ only`,explanation:`Correct. Factor: $\\frac{(x-3)(x+3)}{(x-3)(x+2)} = \\frac{x+3}{x+2}$ for $x \\ne 3$. The simplified form is zero only when $x + 3 = 0$, i.e., $x = -3$.`},{letter:`C`,text:`$x = 3$ only`,explanation:`Incorrect. $x = 3$ makes the denominator zero too, so it is a hole, not a zero.`},{letter:`D`,text:`$x = -2, x = -3$`,explanation:`Incorrect. $x = -2$ makes the denominator zero (vertical asymptote), not a zero of the function.`}],`B`),V(`mc-2-01`,2,`2.3`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Which of the following is an exponential function?`,[{letter:`A`,text:`$f(x) = 5x^2$`,explanation:`Incorrect. This is a power (polynomial) function, not exponential.`},{letter:`B`,text:`$f(x) = 2 \\cdot 3^x$`,explanation:`Correct. Form is $a \\cdot b^x$ with $a = 2$, $b = 3$. Variable is in the exponent.`},{letter:`C`,text:`$f(x) = x^3 + x$`,explanation:`Incorrect. Polynomial function, not exponential.`},{letter:`D`,text:`$f(x) = \\log(x)$`,explanation:`Incorrect. Logarithmic, not exponential.`}],`B`),V(`mc-2-02`,2,`2.2`,`no-calc`,2,`Multiple Representations`,`A function has values $f(0) = 5$, $f(1) = 10$, $f(2) = 20$, $f(3) = 40$. Which of the following best identifies $f$?`,[{letter:`A`,text:`Linear; $f(x) = 5 + 5x$.`,explanation:`Incorrect. First differences are 5, 10, 20 — not constant. Not linear.`},{letter:`B`,text:`Quadratic; $f(x) = 5x^2 + 5$.`,explanation:`Incorrect. Second differences are not constant either: 5, 10 — these are growing.`},{letter:`C`,text:`Exponential; $f(x) = 5 \\cdot 2^x$.`,explanation:`Correct. Successive ratios are constant at 2: $10/5 = 2$, $20/10 = 2$, $40/20 = 2$. Initial value $f(0) = 5$. So $f(x) = 5 \\cdot 2^x$.`},{letter:`D`,text:`Logarithmic; $f(x) = 5 \\log_2(x)$.`,explanation:`Incorrect. $\\log_2(0)$ is undefined, so $f(0) = 5$ wouldn't fit.`}],`C`),V(`mc-2-03`,2,`2.4`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Simplify $\\dfrac{9^x \\cdot 3^{2x}}{27^x}$.`,[{letter:`A`,text:`$1$`,explanation:`Incorrect. Rewriting in base 3: $9^x = 3^{2x}$ and $27^x = 3^{3x}$. The expression becomes $3^{2x + 2x - 3x} = 3^x$, not 1. The expression equals 1 only when $x = 0$.`},{letter:`B`,text:`$3^x$`,explanation:`Correct. $9^x = 3^{2x}$ and $27^x = 3^{3x}$. Expression becomes $\\frac{3^{2x} \\cdot 3^{2x}}{3^{3x}} = 3^{2x + 2x - 3x} = 3^x$.`},{letter:`C`,text:`$3^{2x}$`,explanation:`Incorrect. Exponent error: $2x + 2x - 3x = x$, not $2x$.`},{letter:`D`,text:`$3$`,explanation:`Incorrect. The result depends on $x$.`}],`B`),V(`mc-2-04`,2,`2.7`,`no-calc`,2,`Procedural and Symbolic Fluency`,`If $f(x) = x^2 + 1$ and $g(x) = 2x - 3$, find $(f \\circ g)(2)$.`,[{letter:`A`,text:`$2$`,explanation:`Correct. $g(2) = 2(2) - 3 = 1$. Then $f(1) = 1^2 + 1 = 2$.`},{letter:`B`,text:`$5$`,explanation:`Incorrect. This is $f(2) = 4 + 1 = 5$, not the composition. You stopped after applying $f$ instead of starting with $g$.`},{letter:`C`,text:`$7$`,explanation:`Incorrect. This is $(g \\circ f)(2) = g(5) = 7$, not $(f \\circ g)(2)$. Order matters: $(f \\circ g)(2) = f(g(2))$, so apply $g$ first.`},{letter:`D`,text:`$10$`,explanation:`Incorrect. The composition $(f \\circ g)(2)$ equals 2 — apply $g$ first to get $g(2) = 1$, then $f(1) = 2$.`}],`A`),V(`mc-2-05`,2,`2.8`,`no-calc`,2,`Multiple Representations`,`If $f(x) = 3x + 7$, what is $f^{-1}(x)$?`,[{letter:`A`,text:`$f^{-1}(x) = \\dfrac{x - 7}{3}$`,explanation:`Correct. Set $y = 3x + 7$, swap: $x = 3y + 7$, solve for $y$: $y = (x - 7)/3$.`},{letter:`B`,text:`$f^{-1}(x) = \\dfrac{1}{3x + 7}$`,explanation:`Incorrect. This is the reciprocal of $f$, not the inverse.`},{letter:`C`,text:`$f^{-1}(x) = 3x - 7$`,explanation:`Incorrect. You need to undo BOTH operations of $f$: subtract 7, then divide by 3.`},{letter:`D`,text:`$f^{-1}(x) = \\dfrac{x + 7}{3}$`,explanation:`Incorrect. Sign error: subtracting 7 is correct, not adding.`}],`A`),V(`mc-2-06`,2,`2.9`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Evaluate $\\log_2(32)$.`,[{letter:`A`,text:`$4$`,explanation:`Incorrect. $2^4 = 16$, not 32.`},{letter:`B`,text:`$5$`,explanation:`Correct. $2^5 = 32$, so $\\log_2(32) = 5$.`},{letter:`C`,text:`$8$`,explanation:`Incorrect. $\\log$ of 32 cannot exceed 5 with base 2 since $2^5 = 32$.`},{letter:`D`,text:`$16$`,explanation:`Incorrect. This is the value of $2^4$, not the log.`}],`B`),V(`mc-2-07`,2,`2.12`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Which expression is equivalent to $\\log_5(x^2 y / z^3)$?`,[{letter:`A`,text:`$2\\log_5 x + \\log_5 y - 3 \\log_5 z$`,explanation:`Correct. Use product, quotient, and power rules: $\\log(x^2) = 2\\log x$; $\\log(z^3) = 3\\log z$; product becomes sum, quotient becomes difference.`},{letter:`B`,text:`$\\log_5 x^2 \\cdot \\log_5 y / \\log_5 z^3$`,explanation:`Incorrect. Logs do not distribute over multiplication or division this way.`},{letter:`C`,text:`$2\\log_5 x \\cdot \\log_5 y / 3 \\log_5 z$`,explanation:`Incorrect. Same mistake — logs do not split across multiplication.`},{letter:`D`,text:`$\\log_5 (x^2 + y - z^3)$`,explanation:`Incorrect. Log of product is sum of logs, not log of sum. Treating multiplication as addition inside the log is wrong.`}],`A`),V(`mc-2-08`,2,`2.13`,`calc-required`,2,`Procedural and Symbolic Fluency`,`Solve $3 \\cdot 2^x = 96$ for $x$.`,[{letter:`A`,text:`$x = 5$`,explanation:`Correct. Divide by 3: $2^x = 32 = 2^5$. So $x = 5$.`},{letter:`B`,text:`$x = 6$`,explanation:`Incorrect. $3 \\cdot 2^6 = 192$, not 96.`},{letter:`C`,text:`$x = \\log_{10}(32) \\approx 1.51$`,explanation:`Incorrect. You took base-10 log instead of base-2. Since $2^x = 32$, you need $\\log_2(32) = 5$, not $\\log_{10}(32)$.`},{letter:`D`,text:`$x = \\log(96) - \\log(3) \\approx 1.5$`,explanation:`Incorrect. The expression is correct, but you need to divide by $\\log(2)$ since the base is 2: $x = \\log(32)/\\log(2) = 5$.`}],`A`),V(`mc-2-09`,2,`2.5`,`calc-required`,2,`Multiple Representations`,`A bacteria population starts at 500 and doubles every 4 hours. What is the population after 10 hours?`,[{letter:`A`,text:`$500 \\cdot 2^{10/4} \\approx 2828$`,explanation:`Correct. $P(t) = 500 \\cdot 2^{t/4}$. At $t = 10$: $500 \\cdot 2^{2.5} \\approx 500 \\cdot 5.657 \\approx 2828$.`},{letter:`B`,text:`$500 \\cdot 2^{10} = 512000$`,explanation:`Incorrect. The population doubles every 4 hours, not every hour.`},{letter:`C`,text:`$500 \\cdot 4^{10} \\approx 5 \\times 10^8$`,explanation:`Incorrect. Doubling every 4 hours doesn't mean multiplying by 4. The base is 2; the time unit is 4 hours.`},{letter:`D`,text:`$500 \\cdot 2^{4 \\cdot 10} = 500 \\cdot 2^{40}$`,explanation:`Incorrect. Time should be DIVIDED by 4 (number of doubling periods), not multiplied.`}],`A`),V(`mc-2-10`,2,`2.14`,`calc-required`,2,`Communication and Reasoning`,`A radioactive substance has a half-life of 5 years. If we start with 100 grams, find the time when 25 grams remain.`,[{letter:`A`,text:`$5$ years`,explanation:`Incorrect. After 5 years, only the FIRST half-life has elapsed: 50 grams remain, not 25.`},{letter:`B`,text:`$10$ years`,explanation:`Correct. After 5 years: 50 g (half). After 10 years: 25 g (quarter). Two half-lives.`},{letter:`C`,text:`$15$ years`,explanation:`Incorrect. After 15 years (three half-lives), only 12.5 g would remain.`},{letter:`D`,text:`$25$ years`,explanation:`Incorrect. After 25 years (five half-lives), only $100 \\cdot 0.5^5 = 3.125$ g would remain.`}],`B`),V(`mc-2-11`,2,`2.11`,`no-calc`,1,`Multiple Representations`,`Which is the domain of $f(x) = \\log_3(x - 4)$?`,[{letter:`A`,text:`$x > 4$`,explanation:`Correct. The argument of $\\log$ must be positive: $x - 4 > 0$, so $x > 4$.`},{letter:`B`,text:`$x \\ge 4$`,explanation:`Incorrect. At $x = 4$, $\\log_3(0)$ is undefined (diverges to $-\\infty$).`},{letter:`C`,text:`$x \\ne 4$`,explanation:`Incorrect. Includes $x < 4$, where the argument is negative.`},{letter:`D`,text:`all real numbers`,explanation:`Incorrect. Logarithm is undefined for non-positive arguments.`}],`A`),V(`mc-2-12`,2,`2.10`,`no-calc`,2,`Multiple Representations`,`The graph of $f(x) = \\ln(x)$ is reflected across the line $y = x$. The result is which function?`,[{letter:`A`,text:`$g(x) = e^x$`,explanation:`Correct. Reflection across $y = x$ produces the inverse. The inverse of $\\ln(x)$ is $e^x$.`},{letter:`B`,text:`$g(x) = -\\ln(x)$`,explanation:`Incorrect. Reflection across the $x$-axis would give $-\\ln(x)$, not reflection across $y = x$.`},{letter:`C`,text:`$g(x) = \\ln(-x)$`,explanation:`Incorrect. This is reflection across the $y$-axis.`},{letter:`D`,text:`$g(x) = 1/\\ln(x)$`,explanation:`Incorrect. The inverse function is not the same as the reciprocal.`}],`A`),V(`mc-2-13`,2,`2.13`,`no-calc`,3,`Procedural and Symbolic Fluency`,`Solve $\\log_2(x) + \\log_2(x - 6) = 4$.`,[{letter:`A`,text:`$x = 8$`,explanation:`Correct. Combine: $\\log_2(x(x-6)) = 4 \\Rightarrow x(x-6) = 16 \\Rightarrow x^2 - 6x - 16 = 0$. Factoring: $(x-8)(x+2) = 0$, so $x = 8$ or $x = -2$. Reject $x = -2$ (would make $\\log_2(-2)$ undefined). Answer: $x = 8$.`},{letter:`B`,text:`$x = -2$`,explanation:`Incorrect. $\\log_2(-2)$ is undefined.`},{letter:`C`,text:`$x = 8$ and $x = -2$`,explanation:`Incorrect. Reject $x = -2$ — extraneous due to log domain.`},{letter:`D`,text:`$x = 16$`,explanation:`Incorrect. Setting up correctly gives $x(x-6) = 16$; $x = 16$ does not satisfy this ($16 \\cdot 10 = 160 \\ne 16$).`}],`A`),V(`mc-2-14`,2,`2.1`,`no-calc`,1,`Procedural and Symbolic Fluency`,`A geometric sequence has first term $a_1 = 6$ and common ratio $r = 2$. Find $a_5$.`,[{letter:`A`,text:`$48$`,explanation:`Incorrect. $a_5 = 6 \\cdot 2^{5-1} = 6 \\cdot 16 = 96$.`},{letter:`B`,text:`$96$`,explanation:`Correct. Using $a_n = a_1 \\cdot r^{n-1}$: $a_5 = 6 \\cdot 2^4 = 6 \\cdot 16 = 96$.`},{letter:`C`,text:`$30$`,explanation:`Incorrect. This would be $a_1 + 4r$ (arithmetic), not geometric.`},{letter:`D`,text:`$192$`,explanation:`Incorrect. This is $a_1 \\cdot r^5 = 6 \\cdot 32$, off by one in the exponent.`}],`B`),V(`mc-3-01`,3,`3.3`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Evaluate $\\sin(\\pi/3)$.`,[{letter:`A`,text:`$\\dfrac{1}{2}$`,explanation:`Incorrect. This is $\\sin(\\pi/6)$, not $\\sin(\\pi/3)$.`},{letter:`B`,text:`$\\dfrac{\\sqrt{2}}{2}$`,explanation:`Incorrect. This is $\\sin(\\pi/4)$.`},{letter:`C`,text:`$\\dfrac{\\sqrt{3}}{2}$`,explanation:`Correct. $\\sin(\\pi/3) = \\sqrt{3}/2$. (Note: $\\sin(60°) = \\sqrt{3}/2$.)`},{letter:`D`,text:`$1$`,explanation:`Incorrect. $\\sin(\\pi/2) = 1$, not $\\sin(\\pi/3)$.`}],`C`),V(`mc-3-02`,3,`3.5`,`no-calc`,2,`Multiple Representations`,`A sinusoidal function has amplitude 4, period $\\pi$, midline $y = 1$, and reaches its max at $x = 0$. Which is a valid form?`,[{letter:`A`,text:`$f(x) = 4 \\cos(2x) + 1$`,explanation:`Correct. Amplitude 4: $|a| = 4$. Period $\\pi$: $2\\pi/b = \\pi \\Rightarrow b = 2$. Midline 1: $d = 1$. Max at $x = 0$: cosine starts at max, so use cosine. $f(0) = 4 \\cdot 1 + 1 = 5$ ✓ (max = midline + amplitude = $1 + 4 = 5$).`},{letter:`B`,text:`$f(x) = 4 \\sin(2x) + 1$`,explanation:`Incorrect. $\\sin(0) = 0$, so $f(0) = 1$ — that's the midline, not the max.`},{letter:`C`,text:`$f(x) = 4 \\cos(x) + 1$`,explanation:`Incorrect. $\\cos(x)$ has period $2\\pi$, not $\\pi$.`},{letter:`D`,text:`$f(x) = 4 \\cos(2x) - 1$`,explanation:`Incorrect. Midline is $-1$, not $1$.`}],`A`),V(`mc-3-03`,3,`3.4`,`no-calc`,1,`Multiple Representations`,`What is the period of $f(x) = \\cos(3x)$?`,[{letter:`A`,text:`$\\dfrac{2\\pi}{3}$`,explanation:`Correct. Period of $\\cos(bx)$ is $2\\pi / |b| = 2\\pi/3$.`},{letter:`B`,text:`$3\\pi$`,explanation:`Incorrect. You multiplied by 3 instead of dividing.`},{letter:`C`,text:`$2\\pi$`,explanation:`Incorrect. That's the period of $\\cos(x)$, not $\\cos(3x)$.`},{letter:`D`,text:`$\\dfrac{\\pi}{3}$`,explanation:`Incorrect. You forgot the factor of 2 in $2\\pi$.`}],`A`),V(`mc-3-04`,3,`3.10`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Find all $x \\in [0, 2\\pi)$ such that $\\sin(x) = -\\dfrac{1}{2}$.`,[{letter:`A`,text:`$x = \\pi/6, 5\\pi/6$`,explanation:`Incorrect. These give $\\sin(x) = +1/2$, not $-1/2$.`},{letter:`B`,text:`$x = 7\\pi/6, 11\\pi/6$`,explanation:`Correct. $\\sin(x) = -1/2$ in quadrants III and IV. Reference angle is $\\pi/6$. Quadrant III: $\\pi + \\pi/6 = 7\\pi/6$. Quadrant IV: $2\\pi - \\pi/6 = 11\\pi/6$.`},{letter:`C`,text:`$x = 7\\pi/6$ only`,explanation:`Incorrect. There are two solutions in $[0, 2\\pi)$.`},{letter:`D`,text:`$x = -\\pi/6, -5\\pi/6$`,explanation:`Incorrect. Negative values are outside $[0, 2\\pi)$.`}],`B`),V(`mc-3-05`,3,`3.12`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Simplify $\\sin(2\\theta)$ when $\\sin\\theta = 3/5$ and $\\theta$ is in quadrant II.`,[{letter:`A`,text:`$\\dfrac{24}{25}$`,explanation:`Incorrect. Sign error: $\\cos\\theta < 0$ in quadrant II, so the product $2\\sin\\theta\\cos\\theta$ is negative.`},{letter:`B`,text:`$-\\dfrac{24}{25}$`,explanation:`Correct. $\\sin\\theta = 3/5$, so $\\cos^2\\theta = 1 - 9/25 = 16/25$. Quadrant II: $\\cos\\theta = -4/5$. Then $\\sin(2\\theta) = 2\\sin\\theta\\cos\\theta = 2(3/5)(-4/5) = -24/25$.`},{letter:`C`,text:`$\\dfrac{6}{5}$`,explanation:`Incorrect. The double-angle formula is $2\\sin\\theta\\cos\\theta$, not $2\\sin\\theta$.`},{letter:`D`,text:`$\\dfrac{7}{25}$`,explanation:`Incorrect. This is $\\cos(2\\theta) = 1 - 2\\sin^2\\theta = 1 - 18/25 = 7/25$, not $\\sin(2\\theta)$.`}],`B`),V(`mc-3-06`,3,`3.7`,`calc-required`,2,`Multiple Representations`,`The depth of water in a harbor (in feet) is modeled by $D(t) = 8 + 3 \\sin(\\pi t / 6)$, where $t$ is hours past midnight. What is the maximum water depth?`,[{letter:`A`,text:`$3$ feet`,explanation:`Incorrect. This is the amplitude. Maximum depth is midline plus amplitude.`},{letter:`B`,text:`$8$ feet`,explanation:`Incorrect. This is the midline (average depth), not the maximum.`},{letter:`C`,text:`$11$ feet`,explanation:`Correct. Max = midline + amplitude = $8 + 3 = 11$ feet.`},{letter:`D`,text:`$24$ feet`,explanation:`Incorrect. The amplitude is 3, not 16. Don't multiply.`}],`C`),V(`mc-3-07`,3,`3.9`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Evaluate $\\arccos(-1/2)$.`,[{letter:`A`,text:`$\\pi/3$`,explanation:`Incorrect. $\\arccos(1/2) = \\pi/3$. We need $\\arccos(-1/2)$.`},{letter:`B`,text:`$2\\pi/3$`,explanation:`Correct. Range of arccos is $[0, \\pi]$. We need angle in this range with cosine $= -1/2$. Reference angle $\\pi/3$; in quadrant II this is $\\pi - \\pi/3 = 2\\pi/3$.`},{letter:`C`,text:`$-\\pi/3$`,explanation:`Incorrect. $\\arccos$ has range $[0, \\pi]$, so output cannot be negative.`},{letter:`D`,text:`$4\\pi/3$`,explanation:`Incorrect. Outside arccos's range $[0, \\pi]$.`}],`B`),V(`mc-3-08`,3,`3.13`,`no-calc`,2,`Multiple Representations`,`Convert the polar coordinates $(4, 2\\pi/3)$ to rectangular.`,[{letter:`A`,text:`$(2, 2\\sqrt{3})$`,explanation:`Incorrect. Sign error: $\\cos(2\\pi/3) = -1/2$, so $x = -2$, not $2$.`},{letter:`B`,text:`$(-2, 2\\sqrt{3})$`,explanation:`Correct. $x = r\\cos\\theta = 4 \\cdot (-1/2) = -2$. $y = r\\sin\\theta = 4 \\cdot (\\sqrt{3}/2) = 2\\sqrt{3}$.`},{letter:`C`,text:`$(-2, -2\\sqrt{3})$`,explanation:`Incorrect. $\\sin(2\\pi/3) = \\sqrt{3}/2 > 0$, so $y > 0$.`},{letter:`D`,text:`$(2, -2\\sqrt{3})$`,explanation:`Incorrect. Both $x$ and $y$ have wrong signs.`}],`B`),V(`mc-3-09`,3,`3.14`,`no-calc`,3,`Multiple Representations`,`How many petals does the polar curve $r = 5 \\sin(3\\theta)$ have?`,[{letter:`A`,text:`$3$`,explanation:`Correct. For $r = a\\sin(n\\theta)$ or $a\\cos(n\\theta)$: if $n$ is odd, the curve has exactly $n$ petals.`},{letter:`B`,text:`$6$`,explanation:`Incorrect. The "$n$ even gives $2n$ petals" rule applies for even $n$. Here $n = 3$ is odd, so it has $n = 3$ petals.`},{letter:`C`,text:`$5$`,explanation:`Incorrect. The 5 is the amplitude of the petals, not their count.`},{letter:`D`,text:`$1$`,explanation:`Incorrect. The number of petals depends on the coefficient inside the trig function, not amplitude.`}],`A`),V(`mc-3-10`,3,`3.11`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Find $\\sec(\\pi/4)$.`,[{letter:`A`,text:`$\\sqrt{2}$`,explanation:`Correct. $\\sec(\\pi/4) = 1/\\cos(\\pi/4) = 1/(\\sqrt{2}/2) = 2/\\sqrt{2} = \\sqrt{2}$.`},{letter:`B`,text:`$\\dfrac{\\sqrt{2}}{2}$`,explanation:`Incorrect. This is $\\cos(\\pi/4)$, not $\\sec(\\pi/4)$.`},{letter:`C`,text:`$2$`,explanation:`Incorrect. $\\sec$ is reciprocal of cosine; cosine of $\\pi/4$ is $\\sqrt{2}/2$, not $1/2$.`},{letter:`D`,text:`$\\dfrac{1}{2}$`,explanation:`Incorrect. Computing reciprocal incorrectly.`}],`A`),V(`mc-3-11`,3,`3.8`,`no-calc`,1,`Procedural and Symbolic Fluency`,`What is the period of $f(x) = \\tan(x)$?`,[{letter:`A`,text:`$\\pi/2$`,explanation:`Incorrect. $\\pi/2$ is the location of the first vertical asymptote, not the period.`},{letter:`B`,text:`$\\pi$`,explanation:`Correct. Tangent repeats every $\\pi$ units, NOT $2\\pi$ like sine and cosine.`},{letter:`C`,text:`$2\\pi$`,explanation:`Incorrect. This is the period of sine and cosine. Tangent is half that.`},{letter:`D`,text:`$4\\pi$`,explanation:`Incorrect. The fundamental period of tangent is $\\pi$.`}],`B`),V(`mc-3-12`,3,`3.5`,`calc-required`,2,`Multiple Representations`,`A Ferris wheel makes one rotation every 2 minutes. The lowest point is 2 meters above the ground; the highest is 22 meters. A rider starts at the lowest point. Which models the rider's height (in meters) at time $t$ (in minutes)?`,[{letter:`A`,text:`$h(t) = 10 \\cos(\\pi t) + 12$`,explanation:`Incorrect. At $t = 0$: $h(0) = 10 + 12 = 22$. But rider starts at the lowest point (2 m), not the highest.`},{letter:`B`,text:`$h(t) = -10 \\cos(\\pi t) + 12$`,explanation:`Correct. Amplitude $= (22 - 2)/2 = 10$. Midline $= (22+2)/2 = 12$. Period $= 2 \\Rightarrow b = \\pi$. Starting at lowest point: $-\\cos$ (so $-10\\cos(0) + 12 = -10 + 12 = 2$ ✓).`},{letter:`C`,text:`$h(t) = 10 \\sin(\\pi t) + 12$`,explanation:`Incorrect. At $t = 0$, $h(0) = 12$ (midline), but rider starts at low point of 2.`},{letter:`D`,text:`$h(t) = 10 \\cos(\\pi t / 2) + 12$`,explanation:`Incorrect. Period would be 4 minutes, not 2.`}],`B`),V(`mc-3-13`,3,`3.10`,`calc-required`,2,`Procedural and Symbolic Fluency`,`Find all $x \\in [0, 2\\pi)$ such that $2\\cos^2(x) - 1 = 0$.`,[{letter:`A`,text:`$x = \\pi/4, 7\\pi/4$ only`,explanation:`Incorrect. Missing solutions in quadrants II and III.`},{letter:`B`,text:`$x = \\pi/4, 3\\pi/4, 5\\pi/4, 7\\pi/4$`,explanation:`Correct. $2\\cos^2 x = 1 \\Rightarrow \\cos x = \\pm 1/\\sqrt{2}$. Solutions in $[0, 2\\pi)$: $\\pi/4, 3\\pi/4, 5\\pi/4, 7\\pi/4$.`},{letter:`C`,text:`$x = \\pi/2, 3\\pi/2$`,explanation:`Incorrect. These give $\\cos = 0$, not $\\pm 1/\\sqrt{2}$.`},{letter:`D`,text:`$x = 0, \\pi$`,explanation:`Incorrect. These give $\\cos = \\pm 1$, not $\\pm 1/\\sqrt{2}$.`}],`B`),V(`mc-3-14`,3,`3.6`,`no-calc`,2,`Procedural and Symbolic Fluency`,`For $f(x) = 3\\sin(2x - \\pi/2)$, what is the phase shift?`,[{letter:`A`,text:`$\\pi/2$ to the right`,explanation:`Incorrect. The phase shift is $c/b$ in $\\sin(bx - c)$, where $b = 2$ and $c = \\pi/2$, giving $\\pi/4$, not $\\pi/2$.`},{letter:`B`,text:`$\\pi/4$ to the right`,explanation:`Correct. Rewrite as $\\sin(2(x - \\pi/4))$. Phase shift is $\\pi/4$ to the right.`},{letter:`C`,text:`$\\pi/2$ to the left`,explanation:`Incorrect. Sign error and computation error.`},{letter:`D`,text:`$\\pi/4$ to the left`,explanation:`Incorrect. The minus sign in $\\sin(\\ldots - \\pi/2)$ shifts to the right, not the left.`}],`B`),V(`mc-3-15`,3,`3.12`,`no-calc`,3,`Procedural and Symbolic Fluency`,`Which of the following is equivalent to $\\dfrac{1 - \\cos(2x)}{2}$?`,[{letter:`A`,text:`$\\sin^2 x$`,explanation:`Correct. From the double-angle identity $\\cos(2x) = 1 - 2\\sin^2 x$, rearrange: $1 - \\cos(2x) = 2\\sin^2 x$, so $(1 - \\cos(2x))/2 = \\sin^2 x$.`},{letter:`B`,text:`$\\cos^2 x$`,explanation:`Incorrect. This equals $(1 + \\cos(2x))/2$.`},{letter:`C`,text:`$\\tan^2 x$`,explanation:`Incorrect. Different identity altogether.`},{letter:`D`,text:`$1 - \\cos x$`,explanation:`Incorrect. Cannot just halve $\\cos(2x)$ inside.`}],`A`),V(`mc-3-16`,3,`3.2`,`no-calc`,1,`Communication and Reasoning`,`On the unit circle, an angle $\\theta$ corresponds to the point $(-\\sqrt{3}/2, 1/2)$. What is $\\theta$ if $\\theta \\in [0, 2\\pi)$?`,[{letter:`A`,text:`$\\pi/6$`,explanation:`Incorrect. This is in quadrant I; the given point is in quadrant II.`},{letter:`B`,text:`$5\\pi/6$`,explanation:`Correct. Reference angle is $\\pi/6$ (since $\\cos = \\sqrt{3}/2$, $\\sin = 1/2$). The point is in quadrant II, so $\\theta = \\pi - \\pi/6 = 5\\pi/6$.`},{letter:`C`,text:`$7\\pi/6$`,explanation:`Incorrect. This is in quadrant III, where both coordinates are negative.`},{letter:`D`,text:`$11\\pi/6$`,explanation:`Incorrect. This is in quadrant IV.`}],`B`),V(`mc-1-13`,1,`1.5`,`no-calc`,2,`Procedural and Symbolic Fluency`,`A polynomial $p(x)$ has zeros at $x = -1$ (multiplicity 3) and $x = 4$ (multiplicity 2), and leading coefficient $2$. What is the degree of $p$?`,[{letter:`A`,text:`$2$`,explanation:`Incorrect. That is just the count of distinct zeros.`},{letter:`B`,text:`$5$`,explanation:`Correct. Degree = sum of multiplicities = $3 + 2 = 5$.`},{letter:`C`,text:`$6$`,explanation:`Incorrect. Multiplicities add, they do not multiply.`},{letter:`D`,text:`$10$`,explanation:`Incorrect. Multiplicities add, they do not multiply.`}],`B`),V(`mc-1-14`,1,`1.6`,`no-calc`,2,`Multiple Representations`,`Which polynomial has end behavior $\\lim_{x\\to\\infty} p(x) = -\\infty$ and $\\lim_{x\\to-\\infty} p(x) = \\infty$?`,[{letter:`A`,text:`$p(x) = 3x^4 - x$`,explanation:`Incorrect. Even degree, positive leading coefficient: both ends $\\to \\infty$.`},{letter:`B`,text:`$p(x) = -2x^3 + 5$`,explanation:`Correct. Odd degree with negative leading coefficient gives the described "down on the right, up on the left" pattern.`},{letter:`C`,text:`$p(x) = 4x^3 - x$`,explanation:`Incorrect. Odd degree with positive leading coefficient gives up-right, down-left.`},{letter:`D`,text:`$p(x) = -x^4$`,explanation:`Incorrect. Even degree with negative leading coefficient: both ends $\\to -\\infty$.`}],`B`),V(`mc-1-15`,1,`1.10`,`no-calc`,2,`Procedural and Symbolic Fluency`,`For $r(x) = \\dfrac{x^2 + 2x - 8}{x - 2}$, identify any holes.`,[{letter:`A`,text:`Hole at $(2, 6)$.`,explanation:`Correct. Factor numerator: $x^2 + 2x - 8 = (x-2)(x+4)$. Cancel $(x-2)$ to get $r(x) = x+4$ for $x \\ne 2$. Hole at $x = 2$, $y = 2 + 4 = 6$.`},{letter:`B`,text:`Hole at $(2, 0)$.`,explanation:`Incorrect. After canceling, $r(2)$ from the simplified form is $6$, not $0$.`},{letter:`C`,text:`No hole; vertical asymptote at $x = 2$.`,explanation:`Incorrect. Numerator and denominator share the factor $(x-2)$, so it cancels to a hole.`},{letter:`D`,text:`Hole at $(-4, 0)$.`,explanation:`Incorrect. $x = -4$ is a zero of the simplified $r$, not a hole.`}],`A`),V(`mc-1-16`,1,`1.7`,`no-calc`,1,`Procedural and Symbolic Fluency`,`What is the horizontal asymptote of $r(x) = \\dfrac{2x^4 - x}{5x^2 + 3}$?`,[{letter:`A`,text:`$y = 0$`,explanation:`Incorrect. Numerator degree exceeds denominator degree, so $y = 0$ is not the asymptote.`},{letter:`B`,text:`$y = 2/5$`,explanation:`Incorrect. That ratio applies only when degrees are equal.`},{letter:`C`,text:`No horizontal asymptote.`,explanation:`Correct. Numerator degree (4) exceeds denominator degree (2). The function has no horizontal asymptote.`},{letter:`D`,text:`$y = \\infty$`,explanation:`Incorrect. "Infinity" is not a valid horizontal asymptote.`}],`C`),V(`mc-1-17`,1,`1.4`,`no-calc`,2,`Multiple Representations`,`A polynomial has zeros at $x = 2$ and $x = 1 + i$ with real coefficients. What is the minimum possible degree?`,[{letter:`A`,text:`$2$`,explanation:`Incorrect. A real-coefficient polynomial with $1 + i$ as a zero must also have $1 - i$ as a zero (complex conjugate pair).`},{letter:`B`,text:`$3$`,explanation:`Correct. $1 + i$ forces its conjugate $1 - i$ as a zero too, giving zeros at $2$, $1+i$, $1-i$ — minimum degree 3.`},{letter:`C`,text:`$4$`,explanation:`Incorrect. Three zeros are sufficient; degree 4 is not minimum.`},{letter:`D`,text:`$5$`,explanation:`Incorrect.`}],`B`),V(`mc-1-18`,1,`1.12`,`no-calc`,2,`Procedural and Symbolic Fluency`,`The graph of $g(x) = f(x - 2) + 3$ is obtained from the graph of $f$ by which transformation?`,[{letter:`A`,text:`Shift right 2 and up 3.`,explanation:`Correct. $x - 2$ inside the function shifts right; $+3$ outside shifts up.`},{letter:`B`,text:`Shift left 2 and up 3.`,explanation:`Incorrect. $x - 2$ shifts the graph RIGHT, not left.`},{letter:`C`,text:`Shift right 2 and down 3.`,explanation:`Incorrect. $+3$ outside shifts up.`},{letter:`D`,text:`Shift up 2 and right 3.`,explanation:`Incorrect. The constants are swapped.`}],`A`),V(`mc-1-19`,1,`1.8`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Find all real zeros of $r(x) = \\dfrac{x^2 - 4}{x + 1}$.`,[{letter:`A`,text:`$x = -2, x = 2$`,explanation:`Correct. Numerator factors: $(x-2)(x+2)$. Both zeros are valid since neither makes the denominator zero ($x + 1 = 0 \\Rightarrow x = -1$).`},{letter:`B`,text:`$x = -2, x = 2, x = -1$`,explanation:`Incorrect. $x = -1$ is a vertical asymptote (denominator zero), not a zero of $r$.`},{letter:`C`,text:`$x = -1$ only`,explanation:`Incorrect. $x = -1$ is the location of the vertical asymptote.`},{letter:`D`,text:`No real zeros`,explanation:`Incorrect. Numerator factors with two real zeros.`}],`A`),V(`mc-1-20`,1,`1.13`,`no-calc`,2,`Multiple Representations`,`Which describes the function modeled by the table $f(0)=2, f(1)=5, f(2)=10, f(3)=17, f(4)=26$?`,[{letter:`A`,text:`Linear`,explanation:`Incorrect. First differences are 3, 5, 7, 9 — not constant.`},{letter:`B`,text:`Quadratic`,explanation:`Correct. Second differences: $5-3=2, 7-5=2, 9-7=2$ — constant. That signals a quadratic. Indeed $f(x) = x^2 + 2x + 2$ fits.`},{letter:`C`,text:`Exponential`,explanation:`Incorrect. Successive ratios are not constant.`},{letter:`D`,text:`Cubic`,explanation:`Incorrect. Cubic would require third differences (not second) to be constant.`}],`B`),V(`mc-1-21`,1,`1.7`,`no-calc`,2,`Communication and Reasoning`,`A rational function $r$ has a hole at $x = 1$ and vertical asymptotes at $x = -2$ and $x = 3$. Which factored form is consistent?`,[{letter:`A`,text:`$r(x) = \\dfrac{(x-1)}{(x+2)(x-3)}$`,explanation:`Incorrect. For a hole at $x=1$, $(x-1)$ must appear in BOTH numerator and denominator.`},{letter:`B`,text:`$r(x) = \\dfrac{(x-1)(x-5)}{(x-1)(x+2)(x-3)}$`,explanation:`Correct. $(x-1)$ cancels giving a hole at $x=1$. Remaining denominator $(x+2)(x-3)$ gives vertical asymptotes at $x = -2$ and $x = 3$.`},{letter:`C`,text:`$r(x) = \\dfrac{(x+2)(x-3)}{(x-1)}$`,explanation:`Incorrect. This has a vertical asymptote at $x = 1$, not a hole.`},{letter:`D`,text:`$r(x) = \\dfrac{1}{(x-1)(x+2)(x-3)}$`,explanation:`Incorrect. This has THREE vertical asymptotes (including $x = 1$), not a hole at $x = 1$.`}],`B`),V(`mc-1-22`,1,`1.2`,`no-calc`,2,`Procedural and Symbolic Fluency`,`The average rate of change of $f(x) = x^3$ on $[1, 3]$ equals which value?`,[{letter:`A`,text:`$13$`,explanation:`Correct. $f(3) - f(1) = 27 - 1 = 26$. Divide by $3 - 1 = 2$: AROC $= 13$.`},{letter:`B`,text:`$26$`,explanation:`Incorrect. You forgot to divide by the interval width $b - a = 2$.`},{letter:`C`,text:`$8$`,explanation:`Incorrect. $f(2) = 8$, but that is not the AROC.`},{letter:`D`,text:`$9$`,explanation:`Incorrect. $f(2) - f(1) = 7$, not 9. Also not the AROC.`}],`A`),V(`mc-2-15`,2,`2.6`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Convert the exponential model $f(t) = 4 \\cdot 3^t$ to the form $f(t) = 4 \\cdot e^{kt}$. Find $k$ to four decimal places.`,[{letter:`A`,text:`$k \\approx 1.0986$`,explanation:`Correct. $3^t = e^{t \\ln 3}$, so $k = \\ln 3 \\approx 1.0986$.`},{letter:`B`,text:`$k = 3$`,explanation:`Incorrect. The base must be converted via natural log.`},{letter:`C`,text:`$k \\approx 0.4771$`,explanation:`Incorrect. That is $\\log_{10}(3)$, not $\\ln(3)$.`},{letter:`D`,text:`$k = 1$`,explanation:`Incorrect.`}],`A`),V(`mc-2-16`,2,`2.9`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Evaluate $\\log_3(81) - \\log_3(9)$.`,[{letter:`A`,text:`$2$`,explanation:`Correct. $\\log_3(81) = 4$ and $\\log_3(9) = 2$. Difference $= 2$. (Or use quotient rule: $\\log_3(81/9) = \\log_3(9) = 2$.)`},{letter:`B`,text:`$72$`,explanation:`Incorrect. Logs do not behave like subtracting the arguments.`},{letter:`C`,text:`$6$`,explanation:`Incorrect. You added: $4 + 2 = 6$, but the question asked for the difference.`},{letter:`D`,text:`$\\log_3(72)$`,explanation:`Incorrect. Difference of logs equals log of QUOTIENT, not the difference of arguments.`}],`A`),V(`mc-2-17`,2,`2.13`,`calc-required`,2,`Procedural and Symbolic Fluency`,`Solve $5^x = 40$, to three decimal places.`,[{letter:`A`,text:`$x \\approx 2.292$`,explanation:`Correct. $x = \\log_5(40) = \\ln 40 / \\ln 5 \\approx 3.689 / 1.609 \\approx 2.292$.`},{letter:`B`,text:`$x \\approx 1.602$`,explanation:`Incorrect. That is $\\log_{10}(40)$, not $\\log_5(40)$.`},{letter:`C`,text:`$x = 8$`,explanation:`Incorrect. $5^8$ is far larger than 40.`},{letter:`D`,text:`$x \\approx 0.436$`,explanation:`Incorrect. That is $\\log_{40}(5)$, the reciprocal.`}],`A`),V(`mc-2-18`,2,`2.1`,`no-calc`,2,`Multiple Representations`,`Which sequence is geometric?`,[{letter:`A`,text:`$2, 5, 8, 11, 14, \\ldots$`,explanation:`Incorrect. Successive differences are constant (3) — that is ARITHMETIC.`},{letter:`B`,text:`$3, 6, 12, 24, 48, \\ldots$`,explanation:`Correct. Successive ratios all equal 2: $6/3 = 2$, $12/6 = 2$, etc. Common ratio $r = 2$.`},{letter:`C`,text:`$1, 4, 9, 16, 25, \\ldots$`,explanation:`Incorrect. These are perfect squares; ratios are not constant.`},{letter:`D`,text:`$1, 1, 2, 3, 5, 8, \\ldots$`,explanation:`Incorrect. Fibonacci sequence; neither arithmetic nor geometric.`}],`B`),V(`mc-2-19`,2,`2.11`,`no-calc`,1,`Multiple Representations`,`What is the range of $f(x) = e^x$?`,[{letter:`A`,text:`All real numbers`,explanation:`Incorrect. $e^x$ is always positive — never reaches 0 or below.`},{letter:`B`,text:`$(0, \\infty)$`,explanation:`Correct. $e^x > 0$ for all real $x$, and as $x \\to \\infty$ it covers all positive reals; as $x \\to -\\infty$, $e^x \\to 0^+$.`},{letter:`C`,text:`$[0, \\infty)$`,explanation:`Incorrect. $e^x$ is never exactly 0; the range is open at 0.`},{letter:`D`,text:`$(-\\infty, \\infty)$`,explanation:`Incorrect. Same as choice A.`}],`B`),V(`mc-2-20`,2,`2.7`,`no-calc`,2,`Procedural and Symbolic Fluency`,`If $f(x) = \\sqrt{x}$ and $g(x) = 4x - 3$, find $(f \\circ g)(x)$ and state its domain.`,[{letter:`A`,text:`$\\sqrt{4x - 3}$, domain $x \\ge 3/4$`,explanation:`Correct. $(f \\circ g)(x) = f(g(x)) = \\sqrt{4x - 3}$. Domain: $4x - 3 \\ge 0 \\Rightarrow x \\ge 3/4$.`},{letter:`B`,text:`$\\sqrt{4x - 3}$, domain all reals`,explanation:`Incorrect. Square root requires non-negative argument.`},{letter:`C`,text:`$4\\sqrt{x} - 3$, domain $x \\ge 0$`,explanation:`Incorrect. That is $(g \\circ f)(x)$, not $(f \\circ g)(x)$.`},{letter:`D`,text:`$\\sqrt{4x - 3}$, domain $x \\ge 0$`,explanation:`Incorrect. Domain comes from the inner expression: $4x - 3 \\ge 0$, not $x \\ge 0$.`}],`A`),V(`mc-2-21`,2,`2.14`,`calc-required`,3,`Communication and Reasoning`,`A loan of $\\$10{,}000$ accrues interest continuously at 4% per year. After how many years (to one decimal place) will the balance double?`,[{letter:`A`,text:`$25.0$ years`,explanation:`Incorrect. That uses a simple-interest formula instead of continuous.`},{letter:`B`,text:`$17.3$ years`,explanation:`Correct. $A(t) = 10000 e^{0.04t}$. Set $A(t) = 20000$: $e^{0.04t} = 2 \\Rightarrow t = \\ln 2 / 0.04 \\approx 17.329$ years.`},{letter:`C`,text:`$50.0$ years`,explanation:`Incorrect.`},{letter:`D`,text:`$2.0$ years`,explanation:`Incorrect.`}],`B`),V(`mc-2-22`,2,`2.10`,`no-calc`,2,`Multiple Representations`,`The graph of $y = 2 \\log(x)$ is transformed from $y = \\log(x)$ by which?`,[{letter:`A`,text:`Vertical stretch by 2.`,explanation:`Correct. Multiplying the function output by 2 stretches it vertically by factor 2.`},{letter:`B`,text:`Horizontal compression by 2.`,explanation:`Incorrect. Horizontal compression would be $\\log(2x)$.`},{letter:`C`,text:`Reflection across $x$-axis.`,explanation:`Incorrect. That would be $y = -\\log(x)$.`},{letter:`D`,text:`Shift up by 2.`,explanation:`Incorrect. Shift up would be $\\log(x) + 2$.`}],`A`),V(`mc-3-17`,3,`3.3`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Evaluate $\\cos(5\\pi/6)$.`,[{letter:`A`,text:`$\\dfrac{\\sqrt{3}}{2}$`,explanation:`Incorrect. That is $\\cos(\\pi/6)$. The angle $5\\pi/6$ is in quadrant II where cosine is negative.`},{letter:`B`,text:`$-\\dfrac{\\sqrt{3}}{2}$`,explanation:`Correct. Reference angle is $\\pi/6$. In quadrant II, cosine is negative: $\\cos(5\\pi/6) = -\\sqrt{3}/2$.`},{letter:`C`,text:`$\\dfrac{1}{2}$`,explanation:`Incorrect. That is $\\sin(\\pi/6)$, not $\\cos(5\\pi/6)$.`},{letter:`D`,text:`$-\\dfrac{1}{2}$`,explanation:`Incorrect. Sign is right but magnitude is wrong.`}],`B`),V(`mc-3-18`,3,`3.4`,`no-calc`,2,`Multiple Representations`,`A sinusoidal function has minimum $y = -3$ and maximum $y = 7$. What is its midline?`,[{letter:`A`,text:`$y = 2$`,explanation:`Correct. Midline is the average of max and min: $(7 + (-3))/2 = 4/2 = 2$.`},{letter:`B`,text:`$y = 5$`,explanation:`Incorrect. That is the amplitude, not the midline.`},{letter:`C`,text:`$y = 4$`,explanation:`Incorrect. That is half the range above the min, not the average.`},{letter:`D`,text:`$y = 0$`,explanation:`Incorrect. The midline is shifted up.`}],`A`),V(`mc-3-19`,3,`3.10`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Solve $\\tan x = 1$ for $x \\in [0, 2\\pi)$.`,[{letter:`A`,text:`$x = \\pi/4$ only`,explanation:`Incorrect. Tangent has period $\\pi$, so there is a second solution at $\\pi/4 + \\pi$.`},{letter:`B`,text:`$x = \\pi/4$ and $x = 5\\pi/4$`,explanation:`Correct. $\\tan x = 1$ at the reference angle $\\pi/4$. Tangent has period $\\pi$, so add $\\pi$ to get $5\\pi/4$.`},{letter:`C`,text:`$x = \\pi/4$ and $x = 3\\pi/4$`,explanation:`Incorrect. $\\tan(3\\pi/4) = -1$, not 1.`},{letter:`D`,text:`$x = \\pi/2, 3\\pi/2$`,explanation:`Incorrect. Tangent is undefined at those angles.`}],`B`),V(`mc-3-20`,3,`3.13`,`no-calc`,2,`Multiple Representations`,`Convert the rectangular point $(0, -3)$ to polar coordinates with $r > 0$ and $\\theta \\in [0, 2\\pi)$.`,[{letter:`A`,text:`$(3, \\pi/2)$`,explanation:`Incorrect. $\\theta = \\pi/2$ corresponds to $(0, 3)$, not $(0, -3)$.`},{letter:`B`,text:`$(3, 3\\pi/2)$`,explanation:`Correct. The point lies on the negative $y$-axis. $r = 3$ (distance from origin) and $\\theta = 3\\pi/2$.`},{letter:`C`,text:`$(3, -\\pi/2)$`,explanation:`Incorrect. Equivalent to the right answer but $-\\pi/2 \\notin [0, 2\\pi)$.`},{letter:`D`,text:`$(-3, \\pi/2)$`,explanation:`Incorrect. We require $r > 0$.`}],`B`),V(`mc-3-21`,3,`3.5`,`no-calc`,2,`Procedural and Symbolic Fluency`,`For $f(x) = 4 \\sin(2x) - 1$, what are the amplitude, period, and midline?`,[{letter:`A`,text:`Amplitude 4, period $\\pi$, midline $y = -1$.`,explanation:`Correct. $|a| = 4$. Period $= 2\\pi/|b| = 2\\pi/2 = \\pi$. Vertical shift $d = -1$.`},{letter:`B`,text:`Amplitude 4, period $2\\pi$, midline $y = -1$.`,explanation:`Incorrect. The coefficient $b = 2$ inside the function divides the period: $2\\pi/2 = \\pi$.`},{letter:`C`,text:`Amplitude 2, period $\\pi$, midline $y = 0$.`,explanation:`Incorrect. Amplitude is the OUTSIDE coefficient (4), not the inside one.`},{letter:`D`,text:`Amplitude 4, period $4\\pi$, midline $y = 1$.`,explanation:`Incorrect. The constant $-1$ shifts the midline DOWN, not up.`}],`A`),V(`mc-3-22`,3,`3.12`,`no-calc`,3,`Procedural and Symbolic Fluency`,`Simplify $\\dfrac{1 + \\cos(2x)}{2}$.`,[{letter:`A`,text:`$\\cos^2 x$`,explanation:`Correct. From $\\cos(2x) = 2\\cos^2 x - 1$, rearrange: $1 + \\cos(2x) = 2\\cos^2 x$, so $(1 + \\cos(2x))/2 = \\cos^2 x$.`},{letter:`B`,text:`$\\sin^2 x$`,explanation:`Incorrect. $(1 - \\cos(2x))/2 = \\sin^2 x$. Sign matters.`},{letter:`C`,text:`$1 - \\sin^2 x$`,explanation:`Equivalent to $\\cos^2 x$ — but this option is the long way around. The simplified standard form is $\\cos^2 x$.`},{letter:`D`,text:`$\\tan^2 x$`,explanation:`Incorrect.`}],`A`),V(`mc-3-23`,3,`3.14`,`no-calc`,3,`Multiple Representations`,`How many petals does $r = 4 \\cos(4\\theta)$ have?`,[{letter:`A`,text:`$4$`,explanation:`Incorrect (in this AP context). For $r = a\\cos(n\\theta)$ with $n$ even, the curve has $2n$ petals.`},{letter:`B`,text:`$8$`,explanation:`Correct. When $n$ is EVEN, the rose curve has $2n$ petals: $2 \\cdot 4 = 8$.`},{letter:`C`,text:`$2$`,explanation:`Incorrect.`},{letter:`D`,text:`$16$`,explanation:`Incorrect.`}],`B`),V(`mc-3-24`,3,`3.6`,`no-calc`,2,`Procedural and Symbolic Fluency`,`For $f(x) = 5 \\cos(2(x - \\pi/3)) + 1$, identify the phase shift.`,[{letter:`A`,text:`$\\pi/3$ to the right.`,explanation:`Correct. The function is in the form $a\\cos(b(x - c)) + d$ with $c = \\pi/3$. The graph shifts $\\pi/3$ to the RIGHT.`},{letter:`B`,text:`$\\pi/3$ to the left.`,explanation:`Incorrect. $x - \\pi/3$ shifts right, not left.`},{letter:`C`,text:`$\\pi/6$ to the right.`,explanation:`Incorrect. The factor of 2 outside is not divided into $c$ in this form.`},{letter:`D`,text:`No phase shift.`,explanation:`Incorrect.`}],`A`),V(`mc-3-25`,3,`3.9`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Evaluate $\\arcsin(-1/2)$.`,[{letter:`A`,text:`$-\\pi/6$`,explanation:`Correct. The range of $\\arcsin$ is $[-\\pi/2, \\pi/2]$. Reference angle $\\pi/6$, with the negative input giving negative output: $-\\pi/6$.`},{letter:`B`,text:`$7\\pi/6$`,explanation:`Incorrect. Outside arcsin range.`},{letter:`C`,text:`$11\\pi/6$`,explanation:`Incorrect. Outside arcsin range.`},{letter:`D`,text:`$-\\pi/3$`,explanation:`Incorrect. Wrong reference angle.`}],`A`),V(`mc-3-26`,3,`3.7`,`calc-required`,2,`Multiple Representations`,`A car bobs up and down on its springs after hitting a bump. Its height (in cm above rest) is $h(t) = 6 \\cos(4\\pi t)$. How many full oscillations does it complete in 1 second?`,[{letter:`A`,text:`$1$`,explanation:`Incorrect. The frequency is $4\\pi/(2\\pi) = 2$ cycles per second.`},{letter:`B`,text:`$2$`,explanation:`Correct. Period $= 2\\pi/(4\\pi) = 1/2$ second per oscillation. In 1 second: 2 oscillations.`},{letter:`C`,text:`$4$`,explanation:`Incorrect. You read off the angular frequency, not the cycle frequency.`},{letter:`D`,text:`$4\\pi$`,explanation:`Incorrect. Same mistake.`}],`B`),V(`mc-1-23`,1,`1.5`,`no-calc`,2,`Procedural and Symbolic Fluency`,`A polynomial $p(x)$ has a zero of multiplicity 2 at $x = -1$ and a zero of multiplicity 1 at $x = 4$, with leading coefficient 2. Which expression matches $p(x)$?`,[{letter:`A`,text:`$2(x+1)^2(x-4)$`,explanation:`Correct. Multiplicity 2 at $x=-1$ gives factor $(x+1)^2$; multiplicity 1 at $x=4$ gives $(x-4)$.`},{letter:`B`,text:`$2(x-1)^2(x+4)$`,explanation:`Incorrect. Signs reversed — zero at $-1$ gives $(x+1)$, not $(x-1)$.`},{letter:`C`,text:`$(x+1)^2(x-4)$`,explanation:`Incorrect. Missing the leading coefficient of 2.`},{letter:`D`,text:`$2(x+1)(x-4)^2$`,explanation:`Incorrect. You swapped which zero has multiplicity 2.`}],`A`),V(`mc-1-24`,1,`1.6`,`no-calc`,2,`Multiple Representations`,`A polynomial of even degree has negative leading coefficient. Which statement must be true about its end behavior?`,[{letter:`A`,text:`Both ends $\\to +\\infty$.`,explanation:`Incorrect. That describes even degree with POSITIVE leading coefficient.`},{letter:`B`,text:`Both ends $\\to -\\infty$.`,explanation:`Correct. Even degree means same behavior at both ends; negative coefficient flips both to $-\\infty$.`},{letter:`C`,text:`Left $\\to -\\infty$, right $\\to +\\infty$.`,explanation:`Incorrect. That is odd degree with positive coefficient.`},{letter:`D`,text:`Left $\\to +\\infty$, right $\\to -\\infty$.`,explanation:`Incorrect. That is odd degree with negative coefficient.`}],`B`),V(`mc-1-25`,1,`1.7`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Find the slant asymptote of $r(x) = \\dfrac{2x^2 + 3x - 1}{x + 1}$.`,[{letter:`A`,text:`$y = 2x$`,explanation:`Incorrect. You dropped the constant. Long division yields $2x + 1$ with remainder $-2$.`},{letter:`B`,text:`$y = 2x + 1$`,explanation:`Correct. Long divide $2x^2 + 3x - 1$ by $x + 1$: quotient $2x + 1$, remainder $-2$. Slant asymptote is the quotient.`},{letter:`C`,text:`$y = 2x + 3$`,explanation:`Incorrect. The 3 is the original $x$ coefficient, not the quotient constant after dividing.`},{letter:`D`,text:`No slant asymptote.`,explanation:`Incorrect. Numerator degree is exactly 1 more than denominator — a slant asymptote exists.`}],`B`),V(`mc-1-26`,1,`1.7`,`no-calc`,3,`Procedural and Symbolic Fluency`,`For which value of $x$ does $r(x) = \\dfrac{(x-2)(x+1)}{(x-2)(x-3)}$ have a hole, not a vertical asymptote?`,[{letter:`A`,text:`$x = -1$`,explanation:`Incorrect. $x = -1$ is a zero of the numerator only — it gives a root.`},{letter:`B`,text:`$x = 2$`,explanation:`Correct. $(x-2)$ appears in BOTH numerator and denominator — it cancels, leaving a removable discontinuity (hole).`},{letter:`C`,text:`$x = 3$`,explanation:`Incorrect. $(x-3)$ is in the denominator only — that produces a vertical asymptote, not a hole.`},{letter:`D`,text:`No holes exist.`,explanation:`Incorrect. The shared factor $(x-2)$ produces a hole.`}],`B`),V(`mc-1-27`,1,`1.10`,`no-calc`,2,`Multiple Representations`,`The function $g$ is obtained from $f(x) = x^2$ by the transformation $g(x) = -2 f(x - 3) + 1$. Which describes $g$ correctly?`,[{letter:`A`,text:`Stretch by 2, reflect over $x$-axis, shift right 3 and up 1.`,explanation:`Correct. Multiply by $-2$ stretches by 2 and reflects; $f(x-3)$ shifts right 3; $+1$ shifts up 1.`},{letter:`B`,text:`Compress by 2, reflect over $y$-axis, shift left 3 and down 1.`,explanation:`Incorrect on every count.`},{letter:`C`,text:`Stretch by 2, shift left 3 and up 1.`,explanation:`Incorrect. $x - 3$ shifts RIGHT, not left; you also missed the reflection from the negative.`},{letter:`D`,text:`Reflect over $x$-axis, shift right 3 and down 1.`,explanation:`Incorrect. Missed the vertical stretch of 2 and put the vertical shift in the wrong direction.`}],`A`),V(`mc-1-28`,1,`1.4`,`no-calc`,2,`Procedural and Symbolic Fluency`,`A cubic polynomial with real coefficients has zeros $x = 2$ and $x = 1 + i$. What is the third zero?`,[{letter:`A`,text:`$x = 1 - i$`,explanation:`Correct. Complex zeros of real polynomials come in conjugate pairs. $1 + i$ implies $1 - i$.`},{letter:`B`,text:`$x = -1 - i$`,explanation:`Incorrect. The conjugate of $1 + i$ is $1 - i$, not $-1 - i$.`},{letter:`C`,text:`$x = -2$`,explanation:`Incorrect. There is no reason the real zero would have a negative counterpart.`},{letter:`D`,text:`No third zero exists.`,explanation:`Incorrect. Every cubic has exactly 3 zeros counting multiplicity.`}],`A`),V(`mc-1-29`,1,`1.11`,`calc-required`,2,`Multiple Representations`,`For $f(x) = x^3 - 6x^2 + 9x + 2$, on which interval is $f$ increasing?`,[{letter:`A`,text:`$(-\\infty, 1)$ and $(3, \\infty)$`,explanation:`Correct. $f'(x) = 3x^2 - 12x + 9 = 3(x-1)(x-3)$, positive outside the roots 1 and 3.`},{letter:`B`,text:`$(1, 3)$`,explanation:`Incorrect. Between 1 and 3, $f'$ is negative — $f$ is DEcreasing there.`},{letter:`C`,text:`Everywhere`,explanation:`Incorrect. $f$ has a local max at 1 and local min at 3, so it changes direction.`},{letter:`D`,text:`$(0, 6)$`,explanation:`Incorrect. Those values are not zeros of $f'(x)$.`}],`A`),V(`mc-1-30`,1,`1.2`,`calc-required`,2,`Communication and Reasoning`,`A table shows values of $f$: $f(0)=2, f(2)=5, f(4)=14, f(6)=29, f(8)=50$. The second differences are constant. What is $f(10)$?`,[{letter:`A`,text:`$77$`,explanation:`Correct. First differences: 3, 9, 15, 21. Second differences: 6, 6, 6 — constant. So $f$ is quadratic. Next first difference: 21 + 6 = 27. $f(10) = 50 + 27 = 77$.`},{letter:`B`,text:`$71$`,explanation:`Incorrect. You added the previous first difference (21) without adding the constant second difference.`},{letter:`C`,text:`$80$`,explanation:`Incorrect. Off by one in extending the pattern.`},{letter:`D`,text:`$74$`,explanation:`Incorrect. Mis-extending the first differences.`}],`A`),V(`mc-1-31`,1,`1.8`,`calc-required`,2,`Procedural and Symbolic Fluency`,`A quadratic regression on data gives $f(x) \\approx 1.2x^2 - 0.5x + 3.1$. Use the model to predict $f(4)$ to three decimal places.`,[{letter:`A`,text:`$20.300$`,explanation:`Correct. $1.2(16) - 0.5(4) + 3.1 = 19.2 - 2 + 3.1 = 20.3 = 20.300$.`},{letter:`B`,text:`$24.300$`,explanation:`Incorrect. You forgot to subtract the linear term.`},{letter:`C`,text:`$22.300$`,explanation:`Incorrect. Arithmetic slip on the linear term.`},{letter:`D`,text:`$20.000$`,explanation:`Incorrect. You dropped the constant 3.1.`}],`A`),V(`mc-1-32`,1,`1.12`,`calc-required`,3,`Multiple Representations`,`A regression gives residual plot with a clear curved pattern. Which model is the WORST fit for the data?`,[{letter:`A`,text:`The current linear model (residuals show curvature).`,explanation:`Correct. A pattern in residuals means the current model — typically linear — failed to capture curvature.`},{letter:`B`,text:`A higher-degree polynomial.`,explanation:`Incorrect. Higher-degree models can capture curvature.`},{letter:`C`,text:`An exponential model.`,explanation:`Incorrect. Could fit well if the curvature is exponential.`},{letter:`D`,text:`A quadratic model.`,explanation:`Incorrect. May fit well if the curvature is parabolic.`}],`A`),V(`mc-1-33`,1,`1.5`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Identify the real zeros of $p(x) = x^3 - 4x$.`,[{letter:`A`,text:`$x = 0, 2, -2$`,explanation:`Correct. Factor: $x(x^2 - 4) = x(x-2)(x+2)$. Zeros at $0, 2, -2$.`},{letter:`B`,text:`$x = 0, 4$`,explanation:`Incorrect. $4$ is not a zero — $p(4) = 64 - 16 = 48$.`},{letter:`C`,text:`$x = 2, -2$`,explanation:`Incorrect. Missed the factor of $x$ — $x = 0$ is also a zero.`},{letter:`D`,text:`No real zeros.`,explanation:`Incorrect. The polynomial factors over the reals.`}],`A`),V(`mc-1-34`,1,`1.9`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Simplify $\\dfrac{x^2 - 9}{x^2 + x - 12}$ for $x \\ne 3, -4$.`,[{letter:`A`,text:`$\\dfrac{x + 3}{x + 4}$`,explanation:`Correct. Factor: numerator $(x-3)(x+3)$; denominator $(x-3)(x+4)$. Cancel $(x-3)$.`},{letter:`B`,text:`$\\dfrac{x - 3}{x - 4}$`,explanation:`Incorrect. You factored the denominator wrong: $x^2 + x - 12 = (x-3)(x+4)$, not $(x+3)(x-4)$.`},{letter:`C`,text:`$\\dfrac{x + 3}{x - 4}$`,explanation:`Incorrect. Sign error in denominator factorization.`},{letter:`D`,text:`$\\dfrac{x - 3}{x + 4}$`,explanation:`Incorrect. You cancelled the wrong factor.`}],`A`),V(`mc-1-35`,1,`1.10`,`no-calc`,3,`Communication and Reasoning`,`If $f$ is an even function and $g$ is odd, which is necessarily true about $h(x) = f(x) \\cdot g(x)$?`,[{letter:`A`,text:`$h$ is even.`,explanation:`Incorrect. Even $\\times$ odd $=$ odd, not even.`},{letter:`B`,text:`$h$ is odd.`,explanation:`Correct. $h(-x) = f(-x) g(-x) = f(x) \\cdot (-g(x)) = -h(x)$, the definition of odd.`},{letter:`C`,text:`$h$ is neither even nor odd.`,explanation:`Incorrect. It IS odd by direct check.`},{letter:`D`,text:`Cannot determine.`,explanation:`Incorrect. The product symmetry is fully determined by $f$ and $g$'s symmetries.`}],`B`),V(`mc-2-23`,2,`2.13`,`calc-required`,2,`Procedural and Symbolic Fluency`,`Solve $5 \\cdot 3^{x} = 200$ for $x$, to three decimals.`,[{letter:`A`,text:`$3.358$`,explanation:`Correct. $3^x = 40 \\Rightarrow x = \\log_3 40 = \\ln 40 / \\ln 3 \\approx 3.6889/1.0986 \\approx 3.358$.`},{letter:`B`,text:`$3.689$`,explanation:`Incorrect. You computed $\\ln 40$ but forgot to divide by $\\ln 3$.`},{letter:`C`,text:`$2.484$`,explanation:`Incorrect. Likely $\\log_3 200$ without dividing the 5 first.`},{letter:`D`,text:`$4.825$`,explanation:`Incorrect. Used $\\log_3 (5 \\cdot 200)$ — combined 5 the wrong direction.`}],`A`),V(`mc-2-24`,2,`2.5`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Which best describes the function $f(x) = (1/3)^{x}$?`,[{letter:`A`,text:`Exponential growth, base 1/3.`,explanation:`Incorrect. Base $1/3 < 1$, so this is decay, not growth.`},{letter:`B`,text:`Exponential decay with horizontal asymptote $y = 0$.`,explanation:`Correct. Base between 0 and 1, asymptotic to 0 from above as $x \\to \\infty$.`},{letter:`C`,text:`Linear with negative slope.`,explanation:`Incorrect. Exponential, not linear.`},{letter:`D`,text:`Exponential decay with asymptote $y = 1$.`,explanation:`Incorrect. Asymptote is $y = 0$ unless vertically shifted.`}],`B`),V(`mc-2-25`,2,`2.12`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Rewrite $\\log_5(x^3 y / z^2)$ as a sum/difference of single logarithms.`,[{letter:`A`,text:`$3\\log_5 x + \\log_5 y - 2\\log_5 z$`,explanation:`Correct. Product becomes sum; quotient becomes difference; power becomes coefficient.`},{letter:`B`,text:`$3\\log_5 x + \\log_5 y + 2\\log_5 z$`,explanation:`Incorrect. $z^2$ is in the denominator — its log should be subtracted.`},{letter:`C`,text:`$\\log_5(3x) + \\log_5 y - \\log_5(2z)$`,explanation:`Incorrect. Powers go OUT as coefficients, not multiplied inside.`},{letter:`D`,text:`$3\\log_5(xy) - 2\\log_5 z$`,explanation:`Incorrect. $\\log_5(xy) \\ne \\log_5 x + \\log_5 y$ when multiplied by 3.`}],`A`),V(`mc-2-26`,2,`2.13`,`no-calc`,3,`Procedural and Symbolic Fluency`,`Solve $\\log_2(x + 3) - \\log_2(x - 1) = 2$.`,[{letter:`A`,text:`$x = 7/3$`,explanation:`Correct. $\\log_2 \\frac{x+3}{x-1} = 2 \\Rightarrow \\frac{x+3}{x-1} = 4 \\Rightarrow x + 3 = 4x - 4 \\Rightarrow 3x = 7 \\Rightarrow x = 7/3$. Check domain: $x > 1$. ✓`},{letter:`B`,text:`$x = 1$`,explanation:`Incorrect. Makes the second log undefined.`},{letter:`C`,text:`$x = 7$`,explanation:`Incorrect. Arithmetic error solving the linear equation.`},{letter:`D`,text:`No solution.`,explanation:`Incorrect. $7/3 > 1$ and satisfies the equation.`}],`A`),V(`mc-2-27`,2,`2.3`,`no-calc`,2,`Multiple Representations`,`An arithmetic sequence has $a_1 = 4$ and $a_{10} = 31$. What is the common difference?`,[{letter:`A`,text:`$3$`,explanation:`Correct. $a_n = a_1 + (n-1)d$; $31 = 4 + 9d \\Rightarrow d = 3$.`},{letter:`B`,text:`$2.7$`,explanation:`Incorrect. Used $d = (31-4)/10$; the denominator is $n - 1 = 9$, not $n = 10$.`},{letter:`C`,text:`$3.1$`,explanation:`Incorrect. Off-by-one error.`},{letter:`D`,text:`$27$`,explanation:`Incorrect. That is the total change, not the per-step difference.`}],`A`),V(`mc-2-28`,2,`2.6`,`calc-required`,2,`Communication and Reasoning`,`A loan grows at 6% interest compounded continuously. Approximately how long until it doubles?`,[{letter:`A`,text:`$11.55$ years`,explanation:`Correct. $2 = e^{0.06t} \\Rightarrow t = \\ln 2 / 0.06 \\approx 0.6931 / 0.06 \\approx 11.55$.`},{letter:`B`,text:`$11.67$ years`,explanation:`Incorrect. That is the doubling time at 6% compounded annually using the Rule of 72.`},{letter:`C`,text:`$16.67$ years`,explanation:`Incorrect. That is $1/0.06$, the time to "1 unit" of $rt$ — doubling needs $\\ln 2$, not 1.`},{letter:`D`,text:`$6$ years`,explanation:`Incorrect. The interest rate is 6%, not the doubling time.`}],`A`),V(`mc-2-29`,2,`2.14`,`calc-required`,3,`Multiple Representations`,`A drug concentration in the bloodstream follows $C(t) = 50 e^{-0.25 t}$ mg/L, $t$ in hours. Find the time when concentration drops to 10 mg/L. Round to two decimals.`,[{letter:`A`,text:`$6.44$ hours`,explanation:`Correct. $10 = 50 e^{-0.25t} \\Rightarrow e^{-0.25t} = 0.2 \\Rightarrow -0.25t = \\ln 0.2 \\approx -1.6094 \\Rightarrow t \\approx 6.44$.`},{letter:`B`,text:`$1.61$ hours`,explanation:`Incorrect. You forgot to divide by 0.25.`},{letter:`C`,text:`$4.00$ hours`,explanation:`Incorrect. Time for $C$ to drop to $50/e$, not 10.`},{letter:`D`,text:`$2.77$ hours`,explanation:`Incorrect. Used 0.5 instead of 0.2 in the log step.`}],`A`),V(`mc-2-30`,2,`2.10`,`no-calc`,2,`Multiple Representations`,`The point $(2, 8)$ lies on $y = b^x$. Find $b$.`,[{letter:`A`,text:`$2\\sqrt{2}$`,explanation:`Correct. $b^2 = 8 \\Rightarrow b = \\sqrt{8} = 2\\sqrt{2}$.`},{letter:`B`,text:`$4$`,explanation:`Incorrect. $4^2 = 16$, not 8.`},{letter:`C`,text:`$8$`,explanation:`Incorrect. $8^2 = 64$, not 8.`},{letter:`D`,text:`$\\sqrt{8}/2$`,explanation:`Incorrect. Algebraic slip.`}],`A`),V(`mc-2-31`,2,`2.7`,`calc-required`,2,`Procedural and Symbolic Fluency`,`Use the change-of-base formula to compute $\\log_7 215$, to three decimals.`,[{letter:`A`,text:`$2.760$`,explanation:`Correct. $\\log_7 215 = \\ln 215 / \\ln 7 \\approx 5.3706 / 1.9459 \\approx 2.760$.`},{letter:`B`,text:`$5.371$`,explanation:`Incorrect. That is $\\ln 215$ without dividing by $\\ln 7$.`},{letter:`C`,text:`$1.946$`,explanation:`Incorrect. That is $\\ln 7$.`},{letter:`D`,text:`$30.714$`,explanation:`Incorrect. Computed $215/7$ instead of taking logs.`}],`A`),V(`mc-2-32`,2,`2.2`,`no-calc`,2,`Communication and Reasoning`,`Which sequence shows the FASTEST asymptotic growth as $n \\to \\infty$?`,[{letter:`A`,text:`$a_n = n^{10}$`,explanation:`Incorrect. Polynomial growth is eventually outpaced by exponential.`},{letter:`B`,text:`$a_n = 1.1^n$`,explanation:`Correct. Any exponential with base $> 1$ eventually outpaces any polynomial, regardless of degree or base size.`},{letter:`C`,text:`$a_n = 100 n$`,explanation:`Incorrect. Linear is the slowest of these.`},{letter:`D`,text:`$a_n = (\\log_2 n)^5$`,explanation:`Incorrect. Logarithmic powers grow slower than every polynomial.`}],`B`),V(`mc-3-27`,3,`3.2`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Convert $\\theta = 5\\pi/4$ radians to degrees.`,[{letter:`A`,text:`$225°$`,explanation:`Correct. $5\\pi/4 \\cdot 180/\\pi = 5 \\cdot 45 = 225°$.`},{letter:`B`,text:`$315°$`,explanation:`Incorrect. That is $7\\pi/4$.`},{letter:`C`,text:`$135°$`,explanation:`Incorrect. That is $3\\pi/4$.`},{letter:`D`,text:`$200°$`,explanation:`Incorrect. Arithmetic slip.`}],`A`),V(`mc-3-28`,3,`3.4`,`no-calc`,2,`Multiple Representations`,`The point $(\\sqrt{3}, -1)$ lies on the terminal ray of angle $\\theta$ in standard position. Find $\\sin \\theta$.`,[{letter:`A`,text:`$-1/2$`,explanation:`Correct. $r = \\sqrt{3 + 1} = 2$. $\\sin \\theta = y/r = -1/2$.`},{letter:`B`,text:`$\\sqrt{3}/2$`,explanation:`Incorrect. That is $\\cos \\theta$.`},{letter:`C`,text:`$1/2$`,explanation:`Incorrect. The $y$-coordinate is negative.`},{letter:`D`,text:`$-\\sqrt{3}/2$`,explanation:`Incorrect. Swapped sine and cosine.`}],`A`),V(`mc-3-29`,3,`3.6`,`no-calc`,1,`Procedural and Symbolic Fluency`,`Find the exact value of $\\cos(7\\pi/6)$.`,[{letter:`A`,text:`$-\\sqrt{3}/2$`,explanation:`Correct. $7\\pi/6$ is in Q-III with reference angle $\\pi/6$. Cosine in Q-III is negative, magnitude $\\sqrt{3}/2$.`},{letter:`B`,text:`$\\sqrt{3}/2$`,explanation:`Incorrect. Q-III has negative cosine.`},{letter:`C`,text:`$-1/2$`,explanation:`Incorrect. That is $\\sin(7\\pi/6)$.`},{letter:`D`,text:`$1/2$`,explanation:`Incorrect. Wrong sign and swapped sin/cos.`}],`A`),V(`mc-3-30`,3,`3.11`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Simplify $\\dfrac{\\sin \\theta}{1 - \\cos \\theta} \\cdot \\dfrac{1 + \\cos \\theta}{1 + \\cos \\theta}$.`,[{letter:`A`,text:`$\\dfrac{1 + \\cos \\theta}{\\sin \\theta}$`,explanation:`Correct. $(1-\\cos)(1+\\cos) = 1 - \\cos^2 = \\sin^2$. The product becomes $\\frac{\\sin(1+\\cos)}{\\sin^2} = \\frac{1+\\cos}{\\sin}$.`},{letter:`B`,text:`$\\dfrac{1 - \\cos \\theta}{\\sin \\theta}$`,explanation:`Incorrect. Wrong sign — we multiplied by $(1+\\cos)/(1+\\cos)$.`},{letter:`C`,text:`$\\tan \\theta$`,explanation:`Incorrect. Result is a cotangent-related identity, not $\\tan$.`},{letter:`D`,text:`$\\sin \\theta$`,explanation:`Incorrect. Wrong algebra.`}],`A`),V(`mc-3-31`,3,`3.13`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Solve $2 \\sin \\theta = 1$ on $[0, 2\\pi)$.`,[{letter:`A`,text:`$\\theta = \\pi/6, 5\\pi/6$`,explanation:`Correct. $\\sin \\theta = 1/2$ on $[0, 2\\pi)$ at $\\pi/6$ (Q-I) and $5\\pi/6$ (Q-II).`},{letter:`B`,text:`$\\theta = \\pi/6$ only`,explanation:`Incorrect. Missed the Q-II solution.`},{letter:`C`,text:`$\\theta = \\pi/3, 2\\pi/3$`,explanation:`Incorrect. $\\sin(\\pi/3) = \\sqrt{3}/2$, not 1/2.`},{letter:`D`,text:`$\\theta = \\pi/6, 7\\pi/6$`,explanation:`Incorrect. $7\\pi/6$ has negative sine.`}],`A`),V(`mc-3-32`,3,`3.14`,`calc-required`,2,`Multiple Representations`,`A Ferris wheel has radius 8 m, center at height 10 m, makes a full rotation every 20 seconds, and starts at the bottom at $t = 0$. Which models its height $h(t)$ in meters?`,[{letter:`A`,text:`$h(t) = -8 \\cos(\\pi t/10) + 10$`,explanation:`Correct. Starts at bottom (cosine reflected, offset by amplitude). Period $20 = 2\\pi/B \\Rightarrow B = \\pi/10$. Midline $y = 10$, amplitude 8.`},{letter:`B`,text:`$h(t) = 8 \\cos(\\pi t/10) + 10$`,explanation:`Incorrect. This starts at the TOP ($h(0) = 18$), not the bottom.`},{letter:`C`,text:`$h(t) = 8 \\sin(\\pi t/10) + 10$`,explanation:`Incorrect. This starts at the midline (10 m), not the bottom (2 m).`},{letter:`D`,text:`$h(t) = -8 \\sin(\\pi t/20) + 10$`,explanation:`Incorrect. Period would be 40 s with $B = \\pi/20$.`}],`A`),V(`mc-3-33`,3,`3.15`,`no-calc`,2,`Procedural and Symbolic Fluency`,`Convert the polar point $(r, \\theta) = (4, 2\\pi/3)$ to rectangular coordinates.`,[{letter:`A`,text:`$(-2, 2\\sqrt{3})$`,explanation:`Correct. $x = 4 \\cos(2\\pi/3) = 4(-1/2) = -2$; $y = 4 \\sin(2\\pi/3) = 4(\\sqrt{3}/2) = 2\\sqrt{3}$.`},{letter:`B`,text:`$(2, 2\\sqrt{3})$`,explanation:`Incorrect. $\\cos(2\\pi/3) = -1/2$, so $x$ is negative.`},{letter:`C`,text:`$(-2, -2\\sqrt{3})$`,explanation:`Incorrect. $\\sin(2\\pi/3) = +\\sqrt{3}/2$ in Q-II.`},{letter:`D`,text:`$(-2\\sqrt{3}, 2)$`,explanation:`Incorrect. Swapped $x$ and $y$ values.`}],`A`),V(`mc-3-34`,3,`3.16`,`no-calc`,3,`Multiple Representations`,`The polar curve $r = 2 + 2\\cos \\theta$ is a cardioid. Where on the curve is $r = 0$?`,[{letter:`A`,text:`Only at $\\theta = \\pi$.`,explanation:`Correct. $r = 2 + 2 \\cos \\theta = 0 \\Rightarrow \\cos \\theta = -1 \\Rightarrow \\theta = \\pi$.`},{letter:`B`,text:`At $\\theta = 0$.`,explanation:`Incorrect. $r(0) = 4$, the cardioid's farthest point.`},{letter:`C`,text:`At $\\theta = \\pi/2$ and $3\\pi/2$.`,explanation:`Incorrect. $r(\\pi/2) = r(3\\pi/2) = 2$, not 0.`},{letter:`D`,text:`Nowhere.`,explanation:`Incorrect. The cusp is the point where the cardioid touches the origin.`}],`A`),V(`mc-3-35`,3,`3.10`,`no-calc`,3,`Procedural and Symbolic Fluency`,`Use the angle-sum formula to find $\\cos(75°)$.`,[{letter:`A`,text:`$\\dfrac{\\sqrt{6} - \\sqrt{2}}{4}$`,explanation:`Correct. $\\cos(75°) = \\cos(45°+30°) = \\cos 45 \\cos 30 - \\sin 45 \\sin 30 = \\frac{\\sqrt{2}}{2} \\cdot \\frac{\\sqrt{3}}{2} - \\frac{\\sqrt{2}}{2} \\cdot \\frac{1}{2} = \\frac{\\sqrt{6}-\\sqrt{2}}{4}$.`},{letter:`B`,text:`$\\dfrac{\\sqrt{6} + \\sqrt{2}}{4}$`,explanation:`Incorrect. That is $\\cos(15°) = \\sin(75°)$.`},{letter:`C`,text:`$\\dfrac{\\sqrt{6} + \\sqrt{2}}{2}$`,explanation:`Incorrect. The denominator should be 4 — half-angle/half-product simplification leaves $4$, not $2$.`},{letter:`D`,text:`$\\dfrac{1}{\\sqrt{2}} - \\dfrac{1}{2}$`,explanation:`Incorrect. Skipped multiplying the half-products together before subtracting.`}],`A`),V(`mc-3-36`,3,`3.12`,`no-calc`,2,`Procedural and Symbolic Fluency`,`If $\\sin \\theta = 3/5$ and $\\theta$ is in Q-II, find $\\cos \\theta$.`,[{letter:`A`,text:`$-4/5$`,explanation:`Correct. By Pythagorean identity, $\\cos^2 = 1 - 9/25 = 16/25$, so $\\cos = \\pm 4/5$. In Q-II, cosine is negative.`},{letter:`B`,text:`$4/5$`,explanation:`Incorrect. Q-II has negative cosine.`},{letter:`C`,text:`$-3/4$`,explanation:`Incorrect. That is $-\\tan \\theta$ if you forgot to use Pythagoras.`},{letter:`D`,text:`$-5/4$`,explanation:`Incorrect. Took reciprocal incorrectly.`}],`A`)];

export const mcqByUnit: Record<number, PrecalcMCQ[]> = (() => {
  const m: Record<number, PrecalcMCQ[]> = { 1: [], 2: [], 3: [] };
  for (const q of mcqBank) m[q.unitId].push(q);
  return m;
})();
export const mcqById: Record<string, PrecalcMCQ> = Object.fromEntries(mcqBank.map((q) => [q.id, q]));
